// src/lib/slug.ts
async function generateUniqueSlug(prisma, baseSlug) {
  let slug = baseSlug;
  let counter = 1;
  while (await prisma.exhibitionHall.findUnique({ where: { slug } })) {
    slug = `${baseSlug}-${counter++}`;
  }
  return slug;
}

