// src/services/admin.service.ts
var VALID_ROLES = ["GUEST", "ARTIST", "COLLECTOR", "ADMIN"];
var ALLOWED_ADMIN_STATUSES = ["DRAFT", "LISTED", "IN_EXHIBITION", "RESERVED", "ARCHIVED"];
var AdminService = class {
  constructor(prisma) {
    this.prisma = prisma;
  }
  prisma;
  async stats() {
    const [users, artists, artworks, halls, sales, artKeys] = await Promise.all([
      this.prisma.user.count(),
      this.prisma.artist.count(),
      this.prisma.artwork.count(),
      this.prisma.exhibitionHall.count(),
      this.prisma.sale.count(),
      this.prisma.artKey.count()
    ]);
    return { users, artists, artworks, halls, sales, artKeys };
  }
  async listUsers(params) {
    const { page = 1, pageSize = 20, search, role } = params;
    const where = {};
    if (search) {
      where.OR = [
        { email: { contains: search, mode: "insensitive" } },
        { displayName: { contains: search, mode: "insensitive" } }
      ];
    }
    if (role) where.role = role;
    const [users, total] = await Promise.all([
      this.prisma.user.findMany({
        where,
        select: {
          id: true,
          email: true,
          displayName: true,
          role: true,
          avatarUrl: true,
          createdAt: true,
          updatedAt: true,
          artist: { select: { id: true, verified: true, tier: true } },
          collector: { select: { id: true } },
          _count: { select: { sessions: true } }
        },
        skip: (page - 1) * pageSize,
        take: pageSize,
        orderBy: { createdAt: "desc" }
      }),
      this.prisma.user.count({ where })
    ]);
    return { users, total, page, pageSize };
  }
  async setUserRole(userId, role, changedBy) {
    if (!VALID_ROLES.includes(role)) {
      throw new ValidationError("Invalid role");
    }
    const target = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!target) throw new NotFoundError("User not found");
    if (target.role === role) return target;
    if (target.role === "ADMIN" && role !== "ADMIN") {
      const adminCount = await this.prisma.user.count({ where: { role: "ADMIN" } });
      if (adminCount <= 1) {
        throw new ForbiddenError("Cannot remove the last admin. Assign another admin first.");
      }
    }
    if (userId === changedBy) {
      throw new ForbiddenError("Cannot change your own role.");
    }
    const updated = await this.prisma.user.update({
      where: { id: userId },
      data: { role }
    });
    if (role === "ARTIST") {
      await this.prisma.artist.upsert({
        where: { userId },
        create: { userId, tier: "FREE" },
        update: {}
      });
    }
    if (role === "COLLECTOR") {
      await this.prisma.collector.upsert({
        where: { userId },
        create: {
          userId,
          collections: { create: { title: SAVED_COLLECTION_TITLE, isPublic: false } }
        },
        update: {}
      });
    }
    return updated;
  }
  async verifyArtist(artistId, verified) {
    return this.prisma.artist.update({ where: { id: artistId }, data: { verified } });
  }
  async listArtworks(params) {
    const { page = 1, pageSize = 20, status } = params;
    const where = {};
    if (status) where.status = status;
    const [artworks, total] = await Promise.all([
      this.prisma.artwork.findMany({
        where,
        include: { artist: { include: { user: true } } },
        skip: (page - 1) * pageSize,
        take: pageSize,
        orderBy: { createdAt: "desc" }
      }),
      this.prisma.artwork.count({ where })
    ]);
    return { artworks, total, page, pageSize };
  }
  async setArtworkStatus(artworkId, status) {
    if (!ALLOWED_ADMIN_STATUSES.includes(status)) {
      throw new ValidationError(
        `Admin cannot set status '${status}'. Allowed: ${ALLOWED_ADMIN_STATUSES.join(", ")}. SOLD is set by the sales flow.`
      );
    }
    return this.prisma.artwork.update({ where: { id: artworkId }, data: { status } });
  }
  /** Soft-delete: archive the artwork. Hard deletion is forbidden via admin API. */
  async archiveArtwork(artworkId, force = false) {
    const artwork = await this.prisma.artwork.findUnique({
      where: { id: artworkId },
      include: {
        _count: { select: { sales: true, provenanceRecords: true, artKeys: true } }
      }
    });
    if (!artwork) throw new NotFoundError("Artwork not found");
    if (!force && artwork._count.sales > 0) {
      throw new ForbiddenError(
        `Cannot archive: artwork has ${artwork._count.sales} sale(s). Use force=true to override (this preserves sales and provenance records).`
      );
    }
    if (!force && artwork._count.artKeys > 0) {
      throw new ForbiddenError(
        `Cannot archive: artwork has an issued Art Key. Use force=true to override (the key and provenance chain will be preserved).`
      );
    }
    return this.prisma.artwork.update({
      where: { id: artworkId },
      data: { status: "ARCHIVED" }
    });
  }
};

// src/services/sale.service.ts
var DEFAULT_PAGE_SIZE = 20;
var SaleService = class {
  constructor(prisma) {
    this.prisma = prisma;
  }
  prisma;
  async getPurchasedArtworksByUser(userId, page = 1, pageSize = DEFAULT_PAGE_SIZE) {
    const collector = await this.prisma.collector.findUnique({
      where: { userId }
    });
    if (!collector) return { artworks: [], total: 0, page, pageSize };
    const where = { buyerId: collector.id };
    const [sales, total] = await Promise.all([
      this.prisma.sale.findMany({
        where,
        include: {
          artwork: {
            include: {
              artist: { include: { user: true, hall: true } },
              artKeys: { take: 1 }
            }
          }
        },
        orderBy: { completedAt: "desc" },
        skip: (page - 1) * pageSize,
        take: pageSize
      }),
      this.prisma.sale.count({ where })
    ]);
    const artworks = sales.map((s2) => ({
      id: s2.artwork.id,
      title: s2.artwork.title,
      posterUrl: s2.artwork.posterUrl,
      mediaType: s2.artwork.mediaType,
      category: s2.artwork.category,
      status: s2.artwork.status,
      price: s2.artwork.price?.toString() ?? null,
      currency: s2.artwork.currency,
      purchasePrice: s2.price.toString(),
      purchasedAt: s2.completedAt?.toISOString() ?? s2.createdAt.toISOString(),
      artist: {
        id: s2.artwork.artist.id,
        displayName: s2.artwork.artist.user.displayName,
        hallSlug: s2.artwork.artist.hall?.slug ?? null
      },
      artKey: s2.artwork.artKeys[0] ? { keyCode: s2.artwork.artKeys[0].keyCode } : null
    }));
    return { artworks, total, page, pageSize };
  }
  async getArtistSalesByUser(userId, page = 1, pageSize = DEFAULT_PAGE_SIZE) {
    const artist = await this.prisma.artist.findUnique({
      where: { userId }
    });
    if (!artist) return { sales: [], total: 0, page, pageSize };
    const where = { sellerId: artist.id };
    const [sales, total] = await Promise.all([
      this.prisma.sale.findMany({
        where,
        include: {
          artwork: true,
          buyer: { include: { user: true } }
        },
        orderBy: { createdAt: "desc" },
        skip: (page - 1) * pageSize,
        take: pageSize
      }),
      this.prisma.sale.count({ where })
    ]);
    return {
      sales: sales.map((s2) => ({
        id: s2.id,
        artworkTitle: s2.artwork.title,
        price: s2.price.toString(),
        currency: s2.currency,
        buyerName: s2.buyer.user.displayName ?? s2.buyer.user.email,
        status: s2.status,
        createdAt: s2.createdAt.toISOString()
      })),
      total,
      page,
      pageSize
    };
  }
};

// src/services/follow.service.ts
var FollowService = class {
  constructor(prisma) {
    this.prisma = prisma;
  }
  prisma;
  async followArtist(userId, artistId) {
    const artist = await this.prisma.artist.findUnique({ where: { id: artistId } });
    if (!artist) throw new NotFoundError("Artist not found");
    await this.prisma.follow.upsert({
      where: { followerId_artistId: { followerId: userId, artistId } },
      create: { followerId: userId, artistId },
      update: {}
    });
    const count = await this.prisma.follow.count({ where: { artistId } });
    return { isFollowing: true, followersCount: count };
  }
  async unfollowArtist(userId, artistId) {
    await this.prisma.follow.deleteMany({
      where: { followerId: userId, artistId }
    });
    const count = await this.prisma.follow.count({ where: { artistId } });
    return { isFollowing: false, followersCount: count };
  }
  async getFollowStatus(artistId, userId) {
    const count = await this.prisma.follow.count({ where: { artistId } });
    let isFollowing = false;
    if (userId) {
      const follow = await this.prisma.follow.findUnique({
        where: { followerId_artistId: { followerId: userId, artistId } }
      });
      isFollowing = !!follow;
    }
    return { isFollowing, followersCount: count };
  }
};

// src/services/inquiry.service.ts
var InquiryService = class {
  constructor(prisma) {
    this.prisma = prisma;
  }
  prisma;
  async create(data2) {
    const artwork = await this.prisma.artwork.findUnique({
      where: { id: data2.artworkId },
      include: { artist: true }
    });
    if (!artwork) throw new NotFoundError("Artwork not found");
    const inquiry = await this.prisma.$transaction(async (tx) => {
      const created = await tx.inquiry.create({ data: data2 });
      await tx.notification.create({
        data: {
          userId: artwork.artist.userId,
          type: "INQUIRY_RECEIVED",
          title: `\u041D\u043E\u0432\u044B\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u043E\u0442 ${data2.fromName} / Inquiry from ${data2.fromName}`,
          body: data2.message || data2.fromEmail,
          metadata: { inquiryId: created.id, fromEmail: data2.fromEmail, artworkId: data2.artworkId }
        }
      });
      return created;
    });
    return inquiry;
  }
  async listForArtist(artistId) {
    return this.prisma.inquiry.findMany({
      where: { artwork: { artistId } },
      include: { artwork: { select: { id: true, title: true } } },
      orderBy: { createdAt: "desc" },
      take: 20
    });
  }
};

