function createKdfMigrationRoutes() {
  const routes = new Hono2();
  routes.post(
    "/run-kdf-migration",
    rateLimiter({ windowMs: 6e4, max: 1, message: "Migration already triggered." }),
    async (c5) => {
      const token = c5.req.header("x-seed-token") ?? "";
      const expected = process.env.SEED_TOKEN ?? "";
      const expectedHash = createHash7("sha256").update(expected).digest();
      const actualHash = createHash7("sha256").update(token).digest();
      if (!expected || !token || !timingSafeEqual3(expectedHash, actualHash)) {
        return c5.json(errorResponse("UNAUTHORIZED", "Invalid or missing seed token"), 401);
      }
      const secret = process.env.SECRET_STORE_KEY;
      if (!secret) {
        return c5.json(errorResponse("INTERNAL_ERROR", "SECRET_STORE_KEY not set"), 500);
      }
      const configuredSalt = process.env.KEYSTORE_SALT;
      let saltHex = configuredSalt?.trim();
      if (saltHex === void 0) {
        const saltPath = resolve4(dirname2(fileURLToPath4(import.meta.url)), "../../data/keystore.salt");
        try {
          saltHex = (await readFile5(saltPath, "utf-8")).trim();
        } catch {
          return c5.json(errorResponse("NOT_FOUND", "Salt not found \u2014 set KEYSTORE_SALT or commit keystore.salt first"), 500);
        }
      }
      if (!/^[0-9a-f]{64}$/i.test(saltHex)) {
        return c5.json(errorResponse("INTERNAL_ERROR", "KEYSTORE_SALT must be exactly 64 hexadecimal characters"), 500);
      }
      console.log("\u2192 Running KDF migration (DB only)...");
      const salt = hexToBytes(saltHex);
      const oldKey = await oldDeriveKey(secret);
      const newKey = await derivePbkdf2Key(secret, salt);
      const prisma = c5.get("prisma");
      const keys = await prisma.signingKey.findMany({
        where: { encryptedPrivateKey: { not: prismaNamespace_exports.DbNull } },
        select: { id: true, encryptedPrivateKey: true }
      });
      let ok = 0;
      let already = 0;
      let fail = 0;
      const errors = [];
      const toUpdate = [];
      for (const key of keys) {
        const entry = key.encryptedPrivateKey;
        if (!entry?.ciphertext || !entry?.iv) {
          fail++;
          errors.push(`${key.id.slice(0, 8)}: invalid format`);
          continue;
        }
        try {
          const plaintext = await decryptString(oldKey, entry);
          const newEntry = await encryptString(newKey, plaintext);
          toUpdate.push({ id: key.id, newEntry });
          ok++;
        } catch {
          try {
            await decryptString(newKey, entry);
            already++;
          } catch {
            fail++;
            errors.push(`${key.id.slice(0, 8)}: unknown KDF/secret`);
          }
        }
      }
      if (fail === 0 && toUpdate.length > 0) {
        await prisma.$transaction(
          toUpdate.map(
            ({ id, newEntry }) => prisma.signingKey.update({
              where: { id },
              data: { encryptedPrivateKey: newEntry }
            })
          )
        );
      }
      const result = {
        success: fail === 0,
        message: fail === 0 ? `Migration complete: ${ok} keys re-encrypted with PBKDF2${already > 0 ? `, ${already} already migrated` : ""}` : `Partial migration: ${ok} OK, ${already} already migrated, ${fail} FAILED`,
        saltPrefix: saltHex.slice(0, 16) + "...",
        total: keys.length,
        ok,
        already,
        fail,
        errors: errors.length > 0 ? errors : void 0
      };
      if (fail > 0) {
        return c5.json({ ...result, error: { code: "MIGRATION_FAILED", message: result.message } }, 500);
      }
      return c5.json(result);
    }
  );
  return routes;
}

